def format_tool(t):
    slug, name, cat, desc, pricing, pricingDetail, features, pros, cons, url, altP, priceP, reviewP, rating, alts = t
    feat_str = ", ".join(f'"{f}"' for f in features)
    pros_str = ", ".join(f'"{p}"' for p in pros)
    cons_str = ", ".join(f'"{c}"' for c in cons)
    alts_str = ", ".join(f'"{a}"' for a in alts)

    base = (
        f'  {{ slug: "{slug}", name: "{name}", category: "{cat}", '
        f'description: "{desc}", pricing: "{pricing}", '
        f'pricingDetail: "{pricingDetail}", '
        f'features: [{feat_str}], '
        f'pros: [{pros_str}], '
        f'cons: [{cons_str}], '
        f'url: "{url}", '
        f'hasAlternativePage: {"true" if altP else "false"}, '
        f'hasPricingPage: {"true" if priceP else "false"}, '
        f'hasReviewPage: {"true" if reviewP else "false"}, '
        f'rating: {rating}, '
        f'alternatives: [{alts_str}]'
    )

    rich = RICH_CONTENT.get(slug)
    if rich:
        ld = rich["longDescription"].replace('"', '\\"')
        ev = rich["expertVerdict"].replace('"', '\\"')
        dp = rich["detailedPricing"].replace('"', '\\"')
        bf_str = ", ".join(f'"{b}"' for b in rich["bestFor"])
        kd_str = ", ".join(f'"{k}"' for k in rich["keyDifferentiators"])
        base += (
            f', longDescription: "{ld}", '
            f'expertVerdict: "{ev}", '
            f'detailedPricing: "{dp}", '
            f'bestFor: [{bf_str}], '
            f'keyDifferentiators: [{kd_str}]'
        )

    return base + ' },'

lines = ['import type { Tool } from "@/types";', '', 'export const tools: Tool[] = [']
for t in TOOLS:
    lines.append(format_tool(t))
lines.append('];')
lines.append('')

content = '\n'.join(lines)
with open('/Users/adda247/personal/shipsquad/shipsquad-front/src/data/tools.ts', 'w') as f:
    f.write(content)

print(f"Written {len(TOOLS)} tools to tools.ts ({len(content)} bytes)")

# Verify all required slugs are present
import re
with open('/Users/adda247/personal/shipsquad/shipsquad-front/src/data/comparisons.ts') as f:
    comp_content = f.read()
tool_section = comp_content[comp_content.index('const toolData'):comp_content.index('const traditionalData')]
required = set()
for match in re.finditer(r'\["([^"]+)",\s*"[^"]+",\s*"([^"]+)"', tool_section):
    required.add(match.group(1))
    required.add(match.group(2))

tool_slugs = set(t[0] for t in TOOLS)
missing = required - tool_slugs
if missing:
    print(f"MISSING {len(missing)} required slugs: {sorted(missing)}")
else:
    print("All required comparison slugs present!")
print(f"Extra tools beyond required: {len(tool_slugs - required)}")
